import { patchState, signalStore, withComputed, withMethods, withState } from "@ngrx/signals";
import { DownloadItem, DownloadStatus } from "./beatmap.model";
import { computed, inject } from "@angular/core";
import { OsuDbStore } from "@entities/osu-db";

interface BeatmapState {
    rawQueue: number[];
    statusMap: Record<number, { status: DownloadStatus; progress: number }>;
    isDownloading: boolean;
}

const initialState: BeatmapState = {
    rawQueue: [],
    statusMap: {},
    isDownloading: false
};

export const BeatmapStore = signalStore(
    { providedIn: 'root' },
    withState(initialState),

    withComputed((store, osuDb = inject(OsuDbStore)) => ({
        queue: computed(() => {
            const localIds = osuDb.localBeatmapSetIds();
            return store.rawQueue()
                .filter(id => !localIds.has(id))
                .map(id => ({
                    beatmapSetId: id,
                    ...(store.statusMap()[id] ?? { status: 'pending' as DownloadStatus, progress: 0 })
                }));
        }),

        skippedCount: computed(() =>
            store.rawQueue().filter(id => osuDb.localBeatmapSetIds().has(id)).length
        ),
    })),

    withMethods((store) => ({

        addToQueue(ids: number[]) {
            const existing = new Set(store.rawQueue());
            const statusMap = { ...store.statusMap() };

            const newIds: number[] = [];
            for (const id of ids) {
                if (!existing.has(id)) {
                    newIds.push(id);
                } else {
                    const s = statusMap[id]?.status;
                    if (s === 'done' || s === 'failed') {
                        delete statusMap[id];
                    }
                }
            }

            patchState(store, {
                rawQueue: [...store.rawQueue(), ...newIds],
                statusMap,
            });
        },

        updateStatus(beatmapSetId: number, status: DownloadStatus, progress = 0) {
            patchState(store, {
                statusMap: {
                    ...store.statusMap(),
                    [beatmapSetId]: { status, progress }
                }
            });
        },

        clearQueue() {
            patchState(store, { rawQueue: [], statusMap: {} });
        },

        setDownloading(isDownloading: boolean) {
            patchState(store, { isDownloading });
        },

        removeItem(beatmapSetId: number) {
            const { [beatmapSetId]: _, ...rest } = store.statusMap();
            patchState(store, {
                rawQueue: store.rawQueue().filter(id => id !== beatmapSetId),
                statusMap: rest,
            });
        }
    })),
);

import { Component, computed, inject, ChangeDetectionStrategy } from '@angular/core';
import { CollectionStore } from '@entities/collection';
import { OsuDbStore } from '@entities/osu-db';
import { PackStore } from '@entities/pack';
import { OsuCollection } from '@entities/collection';

interface CollectionEntry {
    collection: OsuCollection;
    available: number;
    added: number;
}

@Component({
    selector: 'app-pack-collection-adder',
    imports: [],
    templateUrl: './pack-collection-adder.component.html',
    styleUrl: './pack-collection-adder.component.css',
    changeDetection: ChangeDetectionStrategy.OnPush,
})
export class PackCollectionAdderComponent {
    readonly collectionStore = inject(CollectionStore);
    readonly packStore = inject(PackStore);
    readonly osuDb = inject(OsuDbStore);

    entries = computed<CollectionEntry[]>(() => {
        const collections = this.collectionStore.collections();
        const diffsByMd5 = this.osuDb.diffsByMd5();
        const addedMd5s = this.packStore.addedMd5s();

        return collections
            .map(col => {
                let available = 0;
                let added = 0;
                for (const md5 of col.md5s) {
                    if (diffsByMd5.has(md5)) {
                        available++;
                        if (addedMd5s.has(md5)) added++;
                    }
                }
                return { collection: col, available, added };
            })
            .filter(e => e.available > 0);
    });

    addCollection(entry: CollectionEntry) {
        this.packStore.addFromCollection(entry.collection);
    }
}

import { patchState, signalStore, withComputed, withMethods, withState } from "@ngrx/signals";
import { OsuCollection } from "./collection.model";
import { computed, inject } from "@angular/core";
import { OsuDbStore } from "@entities/osu-db";
import { OsuBeatmapSet } from "@entities/osu-db/osu-db.model";
import { OsuPathStore, ToastStore } from "@shared/stores"; 
import { invoke } from "@tauri-apps/api/core";


interface CollectionState {
    collections: OsuCollection[];
    selectedCollections: string[];
    isLoading: boolean;
    isLoaded: boolean;
}

const initialState: CollectionState = {
    collections: [],
    selectedCollections: [],
    isLoading: false,
    isLoaded: false
};

export const CollectionStore = signalStore(
    { providedIn: 'root' },
    withState(initialState),

    withComputed((store, osuDb = inject(OsuDbStore)) => {
        const collectionsWithBeatmaps = computed(() => {
            const setsByMd5 = osuDb.beatmapSetsByMd5();
            return store.collections().map(col => {
                const seenIds = new Set<number>();
                const sets = col.md5s
                    .map(md5 => setsByMd5.get(md5))
                    .filter((set): set is OsuBeatmapSet => set !== undefined)
                    .filter(set => {
                        if (seenIds.has(set.beatmapsetId)) return false;
                        seenIds.add(set.beatmapsetId);
                        return true;
                    });
                return { name: col.name, sets };
            });
        });

        const selectedSets = computed(() => {
            const selected = store.selectedCollections();
            const seen = new Set<number>();
            const sets: OsuBeatmapSet[] = [];
            for (const col of collectionsWithBeatmaps()) {
                if (!selected.includes(col.name)) continue;
                for (const set of col.sets) {
                    if (seen.has(set.beatmapsetId)) continue;
                    seen.add(set.beatmapsetId);
                    sets.push(set);
                }
            }
            return sets;
        });

        return {
            collectionsWithBeatmaps,
            selectedSets,
            selectedCount: computed(() => store.selectedCollections().length),
            totalSelectedSets: computed(() => selectedSets().length),
            allSelected: computed(() => {
                const cols = collectionsWithBeatmaps();
                return cols.length > 0 && cols.length === store.selectedCollections().length;
            }),
        };
    }),

    withMethods((store, osuPath = inject(OsuPathStore), toast = inject(ToastStore)) => ({

        async load() {
            const path = osuPath.path();
            if (!path) {
                toast.show('error', 'Osu! path not set');
                throw new Error("Osu! path not set");
            }

            patchState(store, { isLoading: true });

            try {
                const collections = await invoke<OsuCollection[]>("read_osu_collections");
                toast.show('success', `Loaded ${collections.length} collections`);
                patchState(store, { collections, isLoaded: true, isLoading: false });
            } catch (error) {
                patchState(store, { isLoading: false });
                toast.show('error', `Failed to load collections`);
                throw error;
            }
        },

        setCollections(collections: OsuCollection[]) {
            patchState(store, { collections, isLoaded: true, isLoading: false });
        },

        setLoading(isLoading: boolean) {
            patchState(store, { isLoading });
        },

        toggleSelection(name: string) {
            const selected = store.selectedCollections();
            patchState(store, {
                selectedCollections: selected.includes(name)
                    ? selected.filter(c => c !== name)
                    : [...selected, name]
            });
        },

        selectAll() {
            patchState(store, {
                selectedCollections: store.collections().map(c => c.name)
            });
        },

        clearSelection() {
            patchState(store, { selectedCollections: [] });
        },

        reset() {
            patchState(store, initialState);
        }
    })),
);

