export type DownloadStatus = 'pending' | 'downloading' | 'done' | 'failed';

import { inject, Injectable, OnDestroy, signal } from '@angular/core';
import { BeatmapStore } from '@entities/beatmap';
import { UserStore } from '@entities/user';
import { invoke } from '@tauri-apps/api/core';
import { listen, UnlistenFn } from '@tauri-apps/api/event';

interface DownloadProgress {
  beatmapSetId: number;
  progress: number;
  status: 'downloading' | 'done' | 'failed';
}

@Injectable({
  providedIn: 'root',
})
export class BeatmapDownloadService implements OnDestroy {
  private beatmapStore = inject(BeatmapStore);
  private userStore = inject(UserStore);
  private unlisten?: UnlistenFn;

  readonly error = signal<string | null>(null);

  async startDownload() {
    if (this.beatmapStore.isDownloading()) return;

    const pending = this.beatmapStore.queue().filter(i => i.status === 'pending');
    if (pending.length === 0) return;

    if (!this.userStore.user()?.osuSession) return;

    this.error.set(null);
    this.beatmapStore.setDownloading(true);

    this.unlisten = await listen<DownloadProgress>('download:progress', (event) => {
      const { beatmapSetId, progress, status } = event.payload;
      this.beatmapStore.updateStatus(beatmapSetId, status, progress);
    });

    try {
      await invoke('start_downloads', {
        beatmapSetIds: pending.map(i => i.beatmapSetId),
      });
    } catch (e) {
      const msg = typeof e === 'string' ? e : 'Download failed';
      this.error.set(msg);
      for (const item of pending) {
        const q = this.beatmapStore.queue().find(q => q.beatmapSetId === item.beatmapSetId);
        if (q?.status === 'pending') {
          this.beatmapStore.updateStatus(item.beatmapSetId, 'failed');
        }
      }
    } finally {
      this.beatmapStore.setDownloading(false);
      this.unlisten?.();
      this.unlisten = undefined;
    }
  }

  ngOnDestroy() {
    this.unlisten?.();
  }
}

import { ChangeDetectionStrategy, Component, EventEmitter, Input, OnInit, Output, signal } from '@angular/core';

export interface ExportFormat {
  value: string;
  label: string;
}

@Component({
  selector: 'app-export-controls',
  imports: [],
  templateUrl: './export-controls.component.html',
  styleUrl: './export-controls.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ExportControlsComponent implements OnInit {
  @Input({ required: true }) formats: ExportFormat[] = [];
  @Input() count = 0;
  @Input() countLabel = 'beatmapsets';
  @Input() disabled = false;
  @Output() doExport = new EventEmitter<string>();

  readonly selectedFormat = signal('');

  ngOnInit() {
    if (this.formats.length > 0) {
      this.selectedFormat.set(this.formats[0].value);
    }
  }

  export() {
    this.doExport.emit(this.selectedFormat());
  }
}

import { computed, inject } from "@angular/core";
import { CollectionStore } from "@entities/collection";
import { OsuDbStore } from "@entities/osu-db";
import { patchState, signalStore, withComputed, withMethods, withState } from "@ngrx/signals";
import { ToastStore } from "@shared/stores";
import { invoke } from "@tauri-apps/api/core";
import { ParsedImport } from "./import-collection-parser.service";


interface ImportCollectionState {
    parsedImports: ParsedImport[];
    isImporting: boolean;
}

const initialState: ImportCollectionState = {
    parsedImports: [],
    isImporting: false,
};

export const ImportCollectionStore = signalStore(
    { providedIn: 'root' },
    withState(initialState),

    withComputed((store, collectionStore = inject(CollectionStore), osuDB = inject(OsuDbStore)) => {
        const existingMd5sByName = computed(() =>
            new Map(collectionStore.collections().map(c => [c.name, new Set(c.md5s)]))
        );

        // Resolve beatmapsetIds from URL-format imports to all their diffs' md5s
        const resolved = computed(() => {
            const bySetId = osuDB.beatmapSetsBySetId();
            return store.parsedImports().map(imp => {
                const urlMd5s = imp.beatmapsetIds.flatMap(id => {
                    const set = bySetId.get(id);
                    return set ? set.diffs.map(d => d.md5) : [];
                });
                return { name: imp.name, md5s: [...imp.md5s, ...urlMd5s] };
            });
        });

        const collectionsToImport = computed(() =>
            resolved()
                .map(col => {
                    const existing = existingMd5sByName().get(col.name);
                    const md5s = existing
                        ? col.md5s.filter(md5 => !existing.has(md5))
                        : col.md5s;
                    return { ...col, md5s };
                })
                .filter(col => col.md5s.length > 0)
        );

        return {
            collectionsToImport,

            totalMaps: computed(() =>
                collectionsToImport().reduce((sum, c) => sum + c.md5s.length, 0)
            ),

            previewGroups: computed(() => {
                const beatmapSetsByMd5 = osuDB.beatmapSetsByMd5();

                return collectionsToImport().map(col => {
                    const md5s = new Set(col.md5s);
                    const seen = new Set<number>();
                    const sets = [];

                    for (const md5 of md5s) {
                        const set = beatmapSetsByMd5.get(md5);
                        if (!set || seen.has(set.beatmapsetId)) continue;
                        seen.add(set.beatmapsetId);
                        sets.push({ ...set, diffs: set.diffs.filter(d => md5s.has(d.md5)) });
                    }

                    const isExisting = existingMd5sByName().has(col.name);
                    return { name: col.name, sets, isExisting };
                });
            }),
        };
    }),

    withMethods((store, toast = inject(ToastStore)) => ({
        setParsed(parsedImports: ParsedImport[]) {
            patchState(store, { parsedImports });
        },

        clear() {
            patchState(store, initialState);
        },

        async importCollections() {
            const collections = store.collectionsToImport();
            if (collections.length === 0) return;

            patchState(store, { isImporting: true });

            try {
                await invoke('import_collections', { collections });
                toast.show('success', 'Collections imported successfully');
                patchState(store, initialState);
            } catch (error) {
                toast.show('error', 'Failed to import collections');
                patchState(store, { isImporting: false });
                throw error;
            }
        }
    })),
)

