signalStore(
    { providedIn: 'root' },
    withState(initialState),

    withComputed((store, osuDb = inject(OsuDbStore)) => ({
        filteredBeatmaps: computed(() => {
            const { excludedModes, modeFilters, lastPlayed } = store.filters();

            return osuDb.beatmapSets().filter(set => {
                return set.diffs.some(d => {
                    if (lastPlayed !== null && d.lastPlayed !== lastPlayed) return false;
                    if (excludedModes.includes(d.mode)) return false;

                    const mf = modeFilters[d.mode];
                    if (mf) {
                        if (mf.status !== null && set.status !== mf.status) return false;
                        if (mf.minLength !== null && d.length < mf.minLength) return false;
                        if (mf.maxLength !== null && d.length > mf.maxLength) return false;
                        if (mf.minStars !== null && d.stars < mf.minStars) return false;
                        if (mf.maxStars !== null && d.stars > mf.maxStars) return false;
                        if (mf.minOd !== null && d.overallDifficulty < mf.minOd) return false;
                        if (mf.maxOd !== null && d.overallDifficulty > mf.maxOd) return false;
                        if (mf.minHp !== null && d.hpDrain < mf.minHp) return false;
                        if (mf.maxHp !== null && d.hpDrain > mf.maxHp) return false;
                        if (d.mode === 0 || d.mode === 2) {
                            if (mf.minAr !== null && d.approachRate < mf.minAr) return false;
                            if (mf.maxAr !== null && d.approachRate > mf.maxAr) return false;
                        }
                        if (mf.minCs !== null && d.circleSize < mf.minCs) return false;
                        if (mf.maxCs !== null && d.circleSize > mf.maxCs) return false;
                    }

                    return true;
                });
            });
        }),
    })),

    withComputed((store) => ({
        totalFiltered: computed(() => store.filteredBeatmaps().length),
    })),

    withMethods((store) => ({
        setFilters(filters: Partial<Omit<BeatmapFilters, 'modeFilters'>>) {
            patchState(store, { filters: { ...store.filters(), ...filters } });
        },
        setModeFilters(mode: number, filters: Partial<ModeFilters>) {
            const current = store.filters();
            patchState(store, {
                filters: {
                    ...current,
                    modeFilters: {
                        ...current.modeFilters,
                        [mode]: { ...(current.modeFilters[mode] ?? emptyModeFilters()), ...filters },
                    },
                },
            });
        },
        resetFilters() {
            patchState(store, { filters: initialState.filters });
        },
    }))
)

signalStore(
    { providedIn: 'root' },
    withState(initialState),

    withComputed((store, osuDb = inject(OsuDbStore)) => ({
        queue: computed(() => {
            const localIds = osuDb.localBeatmapSetIds();
            return store.rawQueue()
                .filter(id => !localIds.has(id))
                .map(id => ({
                    beatmapSetId: id,
                    ...(store.statusMap()[id] ?? { status: 'pending' as DownloadStatus, progress: 0 })
                }));
        }),

        skippedCount: computed(() =>
            store.rawQueue().filter(id => osuDb.localBeatmapSetIds().has(id)).length
        ),
    })),

    withMethods((store) => ({

        addToQueue(ids: number[]) {
            const existing = new Set(store.rawQueue());
            const statusMap = { ...store.statusMap() };

            const newIds: number[] = [];
            for (const id of ids) {
                if (!existing.has(id)) {
                    newIds.push(id);
                } else {
                    const s = statusMap[id]?.status;
                    if (s === 'done' || s === 'failed') {
                        delete statusMap[id];
                    }
                }
            }

            patchState(store, {
                rawQueue: [...store.rawQueue(), ...newIds],
                statusMap,
            });
        },

        updateStatus(beatmapSetId: number, status: DownloadStatus, progress = 0) {
            patchState(store, {
                statusMap: {
                    ...store.statusMap(),
                    [beatmapSetId]: { status, progress }
                }
            });
        },

        clearQueue() {
            patchState(store, { rawQueue: [], statusMap: {} });
        },

        setDownloading(isDownloading: boolean) {
            patchState(store, { isDownloading });
        },

        removeItem(beatmapSetId: number) {
            const { [beatmapSetId]: _, ...rest } = store.statusMap();
            patchState(store, {
                rawQueue: store.rawQueue().filter(id => id !== beatmapSetId),
                statusMap: rest,
            });
        }
    })),
)

signalStore(
    { providedIn: 'root' },
    withState(initialState),

    withComputed((store, osuDb = inject(OsuDbStore)) => {
        const collectionsWithBeatmaps = computed(() => {
            const setsByMd5 = osuDb.beatmapSetsByMd5();
            return store.collections().map(col => {
                const seenIds = new Set<number>();
                const sets = col.md5s
                    .map(md5 => setsByMd5.get(md5))
                    .filter((set): set is OsuBeatmapSet => set !== undefined)
                    .filter(set => {
                        if (seenIds.has(set.beatmapsetId)) return false;
                        seenIds.add(set.beatmapsetId);
                        return true;
                    });
                return { name: col.name, sets };
            });
        });

        const selectedSets = computed(() => {
            const selected = store.selectedCollections();
            const seen = new Set<number>();
            const sets: OsuBeatmapSet[] = [];
            for (const col of collectionsWithBeatmaps()) {
                if (!selected.includes(col.name)) continue;
                for (const set of col.sets) {
                    if (seen.has(set.beatmapsetId)) continue;
                    seen.add(set.beatmapsetId);
                    sets.push(set);
                }
            }
            return sets;
        });

        return {
            collectionsWithBeatmaps,
            selectedSets,
            selectedCount: computed(() => store.selectedCollections().length),
            totalSelectedSets: computed(() => selectedSets().length),
            allSelected: computed(() => {
                const cols = collectionsWithBeatmaps();
                return cols.length > 0 && cols.length === store.selectedCollections().length;
            }),
        };
    }),

    withMethods((store, osuPath = inject(OsuPathStore), toast = inject(ToastStore)) => ({

        async load() {
            const path = osuPath.path();
            if (!path) {
                toast.show('error', 'Osu! path not set');
                throw new Error("Osu! path not set");
            }

            patchState(store, { isLoading: true });

            try {
                const collections = await invoke<OsuCollection[]>("read_osu_collections");
                toast.show('success', `Loaded ${collections.length} collections`);
                patchState(store, { collections, isLoaded: true, isLoading: false });
            } catch (error) {
                patchState(store, { isLoading: false });
                toast.show('error', `Failed to load collections`);
                throw error;
            }
        },

        setCollections(collections: OsuCollection[]) {
            patchState(store, { collections, isLoaded: true, isLoading: false });
        },

        setLoading(isLoading: boolean) {
            patchState(store, { isLoading });
        },

        toggleSelection(name: string) {
            const selected = store.selectedCollections();
            patchState(store, {
                selectedCollections: selected.includes(name)
                    ? selected.filter(c => c !== name)
                    : [...selected, name]
            });
        },

        selectAll() {
            patchState(store, {
                selectedCollections: store.collections().map(c => c.name)
            });
        },

        clearSelection() {
            patchState(store, { selectedCollections: [] });
        },

        reset() {
            patchState(store, initialState);
        }
    })),
)

signalStore(
    { providedIn: 'root' },
    withState(initialState),

    withComputed((store) => ({
        currentQuery: computed(() => {
            const table = store.selectedTable();
            if (!table) return null;

            const tableInfo = store.tables().find(t => t.name === table);
            if (!tableInfo) return null;

            const includedColumns = tableInfo.columns
                .filter(c => !store.excludedColumns().includes(c.name))
                .map(c => c.name);

            if (includedColumns.length === 0) return null;

            return `SELECT ${includedColumns.join(', ')} FROM ${table}`;
        }),

        currentColumns: computed(() => {
            const tableName = store.selectedTable();
            if (!tableName) return [];

            const table = store.tables().find(t => t.name === tableName);
            return table?.columns ?? [];
        }),

        currentRows: computed((): Record<string, unknown>[] => {
            const tableName = store.selectedTable();
            if (!tableName) return [];
            return (store.results()[tableName] ?? []) as Record<string, unknown>[];
        }),

        columnHeaders: computed(() => {
            const tableName = store.selectedTable();
            if (!tableName) return [];

            const rows = store.results()[tableName] ?? [];

            if (rows.length === 0) return [];
            return Object.keys(rows[0] as Record<string, unknown>);
        })
    })),

    withMethods((store, toast = inject(ToastStore)) => ({
        async load() {
            if (store.isLoaded()) return;

            try {
                const tableNames = await invoke<{ name: string }[]>('get_database_tables');

                const tables: DatabaseTable[] = await Promise.all(
                    tableNames.map(async (t) => {
                        const columns = await invoke<DatabaseColumn[]>('get_table_columns', { tableName: t.name });
                        return { name: t.name, columns };
                    })
                );

                toast.show('success', 'Database tables loaded successfully');
                patchState(store, { tables, isLoaded: true });
            } catch (error) {
                toast.show('error', 'Failed to load database tables');
                patchState(store, { isLoaded: false });
                throw error;
            }
        },

        selectTable(tableName: string) {
            patchState(store, { selectedTable: tableName, excludedColumns: [] });
        },

        toggleColumn(columnName: string) {
            const excludedColumns = store.excludedColumns();

            if (excludedColumns.includes(columnName)) {
                patchState(store, { excludedColumns: excludedColumns.filter(c => c !== columnName) });
            } else {
                patchState(store, { excludedColumns: [...excludedColumns, columnName] });
            }
        },

        async executeQuery() {
            const query = store.currentQuery();
            if (!query) return;

            patchState(store, { isQuerying: true });

            try {
                const results = await invoke<Record<string, unknown>[]>('execute_query', { query });
                patchState(store, { results: { [store.selectedTable()!]: results }, isQuerying: false });
            } catch (error) {
                toast.show('error', 'Failed to execute query');
                patchState(store, { isQuerying: false });
                throw error;
            }
        }
    })),

    withHooks({
        onInit: (store) => {
            effect(() => {
                const query = store.currentQuery();
                if (query) {
                    store.executeQuery();
                }
            });
        }
    })
)

