signalStore(
    { providedIn: 'root' },
    withState(initialState),

    withComputed((store) => ({
        diffsByMd5: computed(() => {
            const map = new Map<string, OsuDiff>();
            for (const set of store.beatmapSets()) {
                for (const diff of set.diffs) {
                    map.set(diff.md5, diff);
                }
            }
            return map;
        }),

        beatmapSetIdByMd5: computed(() => {
            const map = new Map<string, number>();
            for (const set of store.beatmapSets()) {
                for (const diff of set.diffs) {
                    map.set(diff.md5, set.beatmapsetId);
                }
            }
            return map;
        }),

        beatmapSetsByMd5: computed(() => {
            const map = new Map<string, OsuBeatmapSet>();
            for (const set of store.beatmapSets()) {
                for (const diff of set.diffs) {
                    map.set(diff.md5, set);
                }
            }
            return map;
        }),

        totalSets: computed(() => store.beatmapSets().length),

        totalDiffs: computed(() =>
            store.beatmapSets().reduce((sum, s) => sum + s.diffs.length, 0)
        ),

        countByStatus: computed(() => {
            const counts: Record<string, number> = {};
            for (const s of store.beatmapSets()) {
                counts[s.status] = (counts[s.status] || 0) + 1;
            }
            return counts;
        }),

        countByMode: computed(() => {
            const counts: Record<number, number> = {};
            for (const s of store.beatmapSets()) {
                for (const d of s.diffs) {
                    counts[d.mode] = (counts[d.mode] ?? 0) + 1;
                }
            }
            return counts;
        }),

        localBeatmapSetIds: computed(() => new Set(store.beatmapSets().map(s => s.beatmapsetId))),

        beatmapSetsBySetId: computed(() => new Map(store.beatmapSets().map(s => [s.beatmapsetId, s]))),
    })),

    withMethods((store, osuPath = inject(OsuPathStore), toast = inject(ToastStore)) => ({
        setBeatmapSets(beatmapSets: OsuBeatmapSet[]) {
            patchState(store, { beatmapSets, isLoaded: true, isLoading: false });
        },

        setLoading(isLoading: boolean) {
            patchState(store, { isLoading });
        },

        reset() {
            patchState(store, initialState);
        },

        async load() {
            const path = osuPath.path();
            if (!path) {
                toast.show('error', 'Osu! path not set');
                throw new Error("Osu! path not set");
            } 

            patchState(store, { isLoading: true });

            try {
                const beatmapSets = await invoke<OsuBeatmapSet[]>('read_osu_db_full');
                toast.show('success', `Loaded ${beatmapSets.length} beatmap sets from osu!.db`);
                patchState(store, { beatmapSets, isLoaded: true, isLoading: false });
            } catch (error) {
                patchState(store, { isLoading: false });
                toast.show('error', `Failed to load osu!.db`);
                throw error;
            }
        }
    })),
)

signalStore(
  { providedIn: 'root' },
  withState<OsuPathState>({ path: null, error: null, isLoading: false }),

  withMethods((store, toast = inject(ToastStore)) => {
    let detectPromise: Promise<void> | undefined;

    async function doDetect() {
      patchState(store, { isLoading: true });
      try {
        const path = await invoke<string>('get_osu_path');
        toast.show('success', 'Osu! path detected');

        patchState(store, { path, error: null });
        await invoke('save_osu_path', { path });
        toast.show('success', 'Osu! path saved');
      } catch (error) {
        toast.show('error', 'Failed to detect Osu! path');
        patchState(store, { error: error as string });
        detectPromise = undefined;
      } finally {
        patchState(store, { isLoading: false });
      }
    }

    return {
      async detect(): Promise<void> {
        if (!detectPromise) {
          detectPromise = doDetect();
        }
        return detectPromise;
      },

      async selectManually() {
        const selected = await open({
          directory: true,
          multiple: false,
          title: 'Select your osu! folder',
        });

        if (selected) {
          patchState(store, { path: selected as string, error: null });
          detectPromise = Promise.resolve();
          try {
            await invoke('save_osu_path', { path: selected });
            toast.show('success', 'Osu! path saved');
          } catch (e) {
            toast.show('error', 'Failed to save osu! path');
            console.error('Failed to save osu! path:', e);
          }
        }
      },
    };
  }),
)

signalStore(
    { providedIn: 'root' },
    withState(initialState),

    withComputed((store, osuDbStore = inject(OsuDbStore)) => ({
        filteredSets: computed(() => {
            const query = store.searchQuery().toLowerCase().trim();
            const sets = osuDbStore.beatmapSets();

            if (!query) return sets;

            return sets.filter(set =>
                set.title.toLowerCase().includes(query) ||
                set.artist.toLowerCase().includes(query) ||
                set.diffs.some(diff => diff.fileName.toLowerCase().includes(query))
            );
        }),

        addedMd5s: computed(() =>
            new Set(store.selectedDiffs().map(diff => diff.md5))
        ),

        duplicateNames: computed(() => {
            const diffs = store.selectedDiffs();
            const nameCount = new Map<string, number>();
            diffs.forEach(d => {
                if (d.newDiffName.trim() === '') return;
                nameCount.set(d.newDiffName, (nameCount.get(d.newDiffName) ?? 0) + 1);
            });
            return new Set(
                diffs.filter(d => (nameCount.get(d.newDiffName) ?? 0) > 1).map(d => d.md5)
            );
        }),

        hasEmptyNames: computed(() =>
            store.selectedDiffs().some(d => d.newDiffName.trim() === '')
        ),
    })),

    withMethods((store, toastStore = inject(ToastStore), osuDb = inject(OsuDbStore)) => ({
        toggleDiff(diff: SelectedDiff) {
            const diffs = store.selectedDiffs();
            const index = diffs.findIndex(d => d.md5 === diff.md5);

            if (index === -1) {
                patchState(store, { selectedDiffs: [...diffs, diff] });
            } else {
                const newDiffs = [...diffs];
                newDiffs.splice(index, 1);
                patchState(store, { selectedDiffs: newDiffs });
            }
        },

        updateDiffName(diff: SelectedDiff, newDiffName: string) {
            const diffs = store.selectedDiffs();
            const index = diffs.findIndex(d => d.md5 === diff.md5);

            if (index >= 0 && diffs[index].newDiffName !== newDiffName) {
                const newDiffs = [...diffs];
                newDiffs[index] = { ...newDiffs[index], newDiffName };
                patchState(store, { selectedDiffs: newDiffs });
            }
        },

        addFromCollection(collection: OsuCollection) {
            const setsByMd5 = osuDb.beatmapSetsByMd5();
            const diffsByMd5 = osuDb.diffsByMd5();
            const alreadyAdded = store.addedMd5s();

            const newDiffs: SelectedDiff[] = [];
            for (const md5 of collection.md5s) {
                if (alreadyAdded.has(md5)) continue;
                const set = setsByMd5.get(md5);
                const diff = diffsByMd5.get(md5);
                if (!set || !diff) continue;
                newDiffs.push({
                    md5: diff.md5,
                    beatmapsetId: set.beatmapsetId,
                    fileName: diff.fileName,
                    audio: diff.audio,
                    newDiffName: `[${diff.creator}] ${set.artist} - ${set.title} (${diff.diffName})`,
                });
            }

            if (newDiffs.length > 0) {
                patchState(store, { selectedDiffs: [...store.selectedDiffs(), ...newDiffs] });
            }
        },

        setTitle(title: string) {
            patchState(store, { title });
        },

        clear() {
            patchState(store, initialState);
        },

        async createPack() {
            try {
                patchState(store, { isCreating: true });
                await invoke('create_pack', {
                    request: {
                        title: store.title(),
                        finalCreator: store.finalCreator(),
                        diffs: store.selectedDiffs()
                    }
                });
                patchState(store, { isCreating: false });
                toastStore.show('success', `Pack ${store.title()} created successfully!`);
                patchState(store, initialState);
            } catch (error) {
                patchState(store, { isCreating: false });
                toastStore.show('error', 'Failed to create pack');
                throw error;
            }
        },

        setSearchQuery(query: string) {
            patchState(store, { searchQuery: query });
        },

        setFinalCreator(finalCreator: string) {
            patchState(store, { finalCreator });
        },

        setTitleValid(titleValid: boolean) {
            patchState(store, { titleValid });
        }
    })),
)

